package net.minecraft.client.renderer;public class PostChain{public static int created,closed,resized,processed;public Object id;public boolean dead;public PostChain(Object textures,Object resources,Object target,Object id){this.id=id;created++;}public void resize(int w,int h){if(dead)throw new AssertionError("resizing closed filter");resized++;}public void close(){if(dead)throw new AssertionError("double close");dead=true;closed++;}public void process(float partial){if(dead)throw new AssertionError("rendering closed filter");processed++;}}
